const plus=(date,n)=>{const d=parseDay(date);d.setDate(d.getDate()+n);return localISO(d)},parseDay=v=>{const [y,m,d]=String(v||today()).split('-').map(Number);return new Date(y,m-1,d,12)},monthKey=v=>String(v||today()).slice(0,7),months=()=>new Date().toLocaleDateString('es-CO',{month:'long',year:'numeric'});
const dateText=v=>v?parseDay(v).toLocaleDateString('es-CO',{day:'numeric',month:'short',year:'numeric'}):'Sin fecha',days=v=>Math.round((parseDay(v)-parseDay(today()))/86400000),currency=v=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(Number(v)||0),norm=v=>String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
