function convertV1(v){const x=blank();x.shopping=(v.shopping||[]).map(r=>({...r,category:'Otros',price:0}));x.pantry=(v.pantry||[]).map(r=>({...r,category:'Otros'}));x.chores=(v.chores||[]).map(r=>({...r,completed:r.lastDone?[r.lastDone]:[]}));x.bills=(v.bills||[]).map(r=>({...r,category:'Servicios del hogar',repeat:'monthly'}));return x}
