let financeReportScope='mes',cloudState={status:'Sin conectar',sync:false};let page='inicio',submarket='compras',subfinance='resumen',financeScope='mes',financeMonth=monthKey(today()),menuTarget='adulto',menuDate=today(),agendaDate=today(),agendaMonth=monthKey(),chosenCategory='Todas',billView='Todos',editing=null,timer=null;
