async function printFinancial(){const rows=reportEntries(),tot=financeTotals(rows);let html=`<div class="fin-report"><header><h1>Casa en Orden · Informe financiero</h1><p>${financeReportScope==='anio'?financeMonth.slice(0,4):esc(monthLabel(financeMonth))} · Informe ${financeReportScope==='anio'?'anual':'mensual'}</p></header><div class="fin-totals"><div><b>Ingresos</b><strong>${currency(tot.ingreso)}</strong></div><div><b>Egresos</b><strong>${currency(tot.egreso)}</strong></div><div><b>Inversiones</b><strong>${currency(tot.inversion)}</strong></div><div><b>Disponible estimado</b><strong>${currency(tot.ingreso-tot.egreso-tot.inversion)}</strong></div></div><p class="small">Las inversiones se muestran separadas de los gastos. El disponible no es el saldo bancario real.</p><h2>Movimientos (${rows.length})</h2><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Concepto</th><th>Categoría</th><th>Método / cuenta</th><th>Responsable</th><th>Valor</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateText(x.date)}</td><td>${esc(x.type)}</td><td>${esc(x.name)}</td><td>${esc(x.category)}</td><td>${esc(x.method||'—')} · ${esc(accountName(x.accountId))}</td><td>${esc(x.person||'—')}${x.author?' · '+esc(x.author):''}</td><td>${currency(x.amount)}</td></tr>`).join('')}</tbody></table><h2>Soportes adjuntos</h2>`;let count=0;for(const r of rows.filter(r=>r.fileId)){const file=await getFile(r.fileId).catch(()=>null);if(!file){html+=`<p>⚠ Soporte no disponible para ${esc(r.name)}.</p>`;continue}count++;if(file.type.startsWith('image/')){let dataurl=await blobToDataUrl(file.blob);html+=`<section class="receipt"><h3>${esc(r.name)} · ${dateText(r.date)}</h3><p>${esc(file.name)}</p><img src="${dataurl}" alt="Soporte de ${esc(r.name)}"></section>`}else{html+=`<p>📎 ${esc(r.name)} · ${esc(file.name)} (PDF original guardado en este iPhone; no incluido en la vista de impresión. Usa el botón «Generar PDF» para incorporarlo.)</p>`}}if(!count)html+='<p>Este mes no hay comprobantes adjuntos.</p>';html+='</div>';printDoc(html)}
function dbOpen(){return new Promise((resolve,reject)=>{let q=indexedDB.open('casa-en-orden-v3-1-local',1);q.onupgradeneeded=()=>{if(!q.result.objectStoreNames.contains('supports'))q.result.createObjectStore('supports',{keyPath:'id'})};q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
async function storeFile(file){const db=await dbOpen();return new Promise((resolve,reject)=>{const tx=db.transaction('supports','readwrite');tx.objectStore('supports').put(file);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function getFile(fid){const db=await dbOpen();return new Promise((resolve,reject)=>{const tx=db.transaction('supports','readonly');const q=tx.objectStore('supports').get(fid);q.onsuccess=async()=>{db.close();if(q.result){resolve(q.result)}else if(cloudConf?.auto){try{resolve(await cloudDownloadSupport(fid))}catch{resolve(null)}}else resolve(null)};q.onerror=()=>{db.close();reject(q.error)}})}
async function allFiles(){const db=await dbOpen();return new Promise((resolve,reject)=>{const tx=db.transaction('supports','readonly');const q=tx.objectStore('supports').getAll();q.onsuccess=()=>{db.close();resolve(q.result)};q.onerror=()=>{db.close();reject(q.error)}})}
async function deleteFile(fid){if(!fid)return;const db=await dbOpen();return new Promise((resolve,reject)=>{const tx=db.transaction('supports','readwrite');tx.objectStore('supports').delete(fid);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
