function downloadBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function viewFile(fid){try{let f=await getFile(fid);if(!f){toast('No se encontró el soporte en este iPhone');return}downloadBlob(f.blob,f.name)}catch(e){alert('No se pudo abrir el soporte: '+e.message)}}
async function blobToDataUrl(blob){return new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
async function makeBackup(){try{let fs=await allFiles(),docs=await Promise.all(fs.map(async x=>({id:x.id,name:x.name,type:x.type,base64:await blobToDataUrl(x.blob)})));let payload={format:'casa-en-orden-v3-1-preview',createdAt:new Date().toISOString(),data,attachments:docs};downloadBlob(new Blob([JSON.stringify(payload)],{type:'application/json'}),`casa-en-orden-3-respaldo-${today()}.json`);toast('Respaldo creado: guárdalo en Archivos o iCloud')}catch(e){alert('No se pudo preparar el respaldo: '+e.message)}}
async function loadBackup(file){if(!file)return;try{if(file.size>28*1024*1024)throw Error('Respaldo demasiado grande (máximo 28 MB).');let payload=JSON.parse(await file.text());let d=payload.data||payload;if(!d||(!Array.isArray(d.shopping)||!Array.isArray(d.pantry)||!Array.isArray(d.bills)||!Array.isArray(d.chores)))throw Error('Archivo no reconocido');if(!confirm('¿Restaurar esta copia? Se reemplazarán los datos de la versión de prueba, pero no la versión 1.0.'))return;let next={...blank(),...d,version:3};if(Array.isArray(payload.attachments)){for(const f of payload.attachments){if(!f.id||!/^data:(image\/|application\/pdf)/.test(f.base64||''))continue;const response=await fetch(f.base64);const b=await response.blob();await storeFile({id:f.id,name:String(f.name).slice(0,130),type:f.type,blob:b})}}data=next;save();render();toast('Prueba restaurada con éxito')}catch(e){alert('No se pudo restaurar: '+e.message)}finally{$('#restoreFile').value=''}}
