function printShopping(){let html=`<div class="printed-cover"><h1>🛒 Lista de mercado y despensa</h1><p>${dateText(today())} · Presupuesto: ${currency(data.budget)}</p></div>`;for(const cat of cats){let items=data.shopping.filter(x=>x.category===cat&&!x.checked);if(!items.length)continue;html+=`<h2>${esc(cat)}</h2><table><tr><th>Marcar</th><th>Producto</th><th>Cantidad</th><th>Precio estimado</th></tr>${items.map(x=>`<tr><td>☐</td><td>${esc(x.name)}</td><td>${esc(x.qty)}</td><td>${currency(x.price)}</td></tr>`).join('')}</table>`}html+=`<p><strong>Total estimado pendiente: ${currency(data.shopping.filter(x=>!x.checked).reduce((a,b)=>a+Number(b.price||0),0))}</strong></p>`;printDoc(html)};

