document.addEventListener('click',e=>{let el=e.target.closest('[data-page],[data-action],[data-submarket],[data-finance-tab],[data-menu-target],[data-shift-menu],[data-shift-month],[data-agenda-date]');if(!el){if(e.target.id==='shade')close();return}if(el.dataset.page){goto(el.dataset.page);return}if(el.dataset.submarket){submarket=el.dataset.submarket;chosenCategory='Todas';render();return}if(el.dataset.financeTab){subfinance=el.dataset.financeTab;render();return}if(el.dataset.menuTarget){menuTarget=el.dataset.menuTarget;render();return}if(el.dataset.shiftMenu){adjustMenu(Number(el.dataset.shiftMenu));return}if(el.dataset.shiftMonth){let d=parseDay(agendaMonth+'-01');d.setMonth(d.getMonth()+Number(el.dataset.shiftMonth));agendaMonth=monthKey(localISO(d));agendaDate=agendaMonth+'-01';render();return}if(el.dataset.agendaDate){agendaDate=el.dataset.agendaDate;agendaMonth=monthKey(agendaDate);render();return}const a=el.dataset.action;if(actions[a])actions[a](el.dataset.id)});
document.addEventListener('change',e=>{let x=e.target;if(x.id==='catpick'){chosenCategory=x.value;render()}if(x.id==='financeScope'){financeScope=x.value;render()}if(x.id==='financeMonth'){financeMonth=x.value||monthKey(today());render()}if(x.id==='reportScope'){financeReportScope=x.value;render()}if(x.id==='billFilter'){billView=x.value;render()}if(x.id==='restoreFile')loadBackup(x.files?.[0]);if(x.closest('#reportPreviewConfig'))updateReportPreview();if(x.id==='generic-print-theme'){let t=$('#generic-doc-preview');if(t)t.classList.toggle('mono-print',x.value==='economico')}if(x.dataset.toggleShopping){let p=data.shopping.find(r=>r.id===x.dataset.toggleShopping);if(p){p.checked=x.checked;save();render()}}if(x.dataset.toggleChore){let t=data.chores.find(r=>r.id===x.dataset.toggleChore);if(t){let list=t.completed||[];t.completed=x.checked?[...new Set([...list,today()])]:list.filter(d=>d!==today());save();render()}}});
document.addEventListener('submit',async e=>{if(e.target.id==='v3Form'){e.preventDefault();await submitExtra(e.target);return}if(e.target.id==='entryForm'){e.preventDefault();await submitForm(e.target)}if(e.target.id==='budgetForm'){e.preventDefault();data.budget=Math.max(0,Math.round(Number(new FormData(e.target).get('budget'))||0));save();close();render();toast('Presupuesto actualizado')}if(e.target.id==='babyForm'){e.preventDefault();let f=new FormData(e.target);data.babyAge=Math.max(6,Math.min(36,Number(f.get('babyAge'))||8));data.allergies=String(f.get('allergies')||'').slice(0,500);data.introduced=String(f.get('introduced')||'').slice(0,600);save();close();render();toast('Preferencias guardadas')}});
